//! JavaScript normalization shared by the CLI and compiler-output tests.
use oxc_allocator::Allocator;
use oxc_ast::ast::*;
use oxc_ast_visit::{VisitMut, walk_mut};
use oxc_codegen::{Codegen, CodegenOptions, CommentOptions, IndentChar};
use oxc_parser::{ParseOptions, Parser};
use oxc_span::{GetSpan, SourceType};

/// Normalization modes. File-envelope text is preserved even with `strip_comments`.
#[derive(Clone, Copy, Debug, Default)]
pub struct ReformatOptions {
    pub strip_comments: bool,
    /// Preserve lines through the generated header and recognized trailing file comments.
    /// Without a header, arbitrary file directives cannot be distinguished from JavaScript.
    pub split_file: bool,
    /// Remove block comments before numeric literals (whitespace/opening parentheses allowed).
    pub drop_decoration_comments: bool,
}

const HEADER: &str = "// Generated by ReScript, PLEASE EDIT WITH CARE";
const EMPTY: &str = "/* This output is empty. Its source's type definitions, externals and/or unused code got optimized away. */";

fn is_trailer(text: &str) -> bool {
    text == "/* No side effect */"
        || text == EMPTY
        || (text.starts_with("/* ") && text.ends_with(" Not a pure module */"))
        || text.starts_with("//# sourceMappingURL=")
}

#[derive(Default)]
struct Normalize {
    numbers: Vec<u32>,
    jsx_sequences: Vec<oxc_span::Span>,
}

impl<'a> VisitMut<'a> for Normalize {
    fn visit_numeric_literal(&mut self, literal: &mut NumericLiteral<'a>) {
        self.numbers.push(literal.span.start);
    }

    fn visit_jsx_expression_container(&mut self, container: &mut JSXExpressionContainer<'a>) {
        walk_mut::walk_jsx_expression_container(self, container);
        if let JSXExpression::SequenceExpression(sequence) = &container.expression {
            self.jsx_sequences.push(sequence.span());
        }
    }
}

// OXC 0.158.0 ignores explicit ParenthesizedExpression nodes in codegen.
// Its parser recovers JSX sequences with precise spans despite diagnosing them.
// Use those spans (not a textual comma search) to repair the generated output.
fn wrap_jsx_sequences(code: &mut String) -> Result<(), String> {
    let allocator = Allocator::default();
    let mut parsed = Parser::new(&allocator, code, SourceType::mjs().with_jsx(true)).parse();
    let mut visitor = Normalize::default();
    visitor.visit_program(&mut parsed.program);
    let mut insertions = Vec::new();
    for span in visitor.jsx_sequences {
        insertions.push((span.start as usize, '('));
        insertions.push((span.end as usize, ')'));
    }
    insertions.sort_unstable();
    for (offset, character) in insertions.into_iter().rev() {
        code.insert(offset, character);
    }
    let checked = Parser::new(&allocator, code, SourceType::mjs().with_jsx(true)).parse();
    if checked.diagnostics.is_empty() {
        Ok(())
    } else {
        Err(checked
            .diagnostics
            .iter()
            .map(|e| format!("{e:?}"))
            .collect::<Vec<_>>()
            .join("\n"))
    }
}

/// Reformat a module (JSX enabled), returning all parser diagnostics on failure.
/// JSX comma expressions are always repaired, independently of the optional modes.
pub fn reformat(source: &str, options: ReformatOptions) -> Result<String, String> {
    let preamble_end = if options.split_file {
        let mut offset = 0;
        source
            .split_inclusive('\n')
            .find_map(|line| {
                offset += line.len();
                (line.trim_end_matches(['\r', '\n']) == HEADER).then_some(offset)
            })
            .unwrap_or(0)
    } else {
        0
    };
    let (preamble, body) = source.split_at(preamble_end);
    let allocator = Allocator::default();
    let mut parsed = Parser::new(&allocator, body, SourceType::mjs().with_jsx(true))
        .with_options(ParseOptions {
            preserve_parens: false,
            ..ParseOptions::default()
        })
        .parse();
    if !parsed.diagnostics.is_empty() {
        return Err(parsed
            .diagnostics
            .iter()
            .map(|e| format!("{e:?}"))
            .collect::<Vec<_>>()
            .join("\n"));
    }
    // Only parser-recognized comments can form a trailer: a matching line inside
    // a template literal or raw string must remain part of the AST.
    let mut trailer_start = body.len();
    if options.split_file {
        for comment in parsed.program.comments.iter().rev() {
            let start = comment.span.start as usize;
            let end = comment.span.end as usize;
            if !body[end..trailer_start].trim().is_empty() || !is_trailer(&body[start..end]) {
                break;
            }
            trailer_start = start;
        }
    }
    let has_trailer = trailer_start < body.len();
    if has_trailer {
        // Preserve the exact gap after the last body token, as part of the envelope.
        while trailer_start > 0 && body.as_bytes()[trailer_start - 1].is_ascii_whitespace() {
            trailer_start -= 1;
        }
    }
    let mut normalize = Normalize::default();
    normalize.visit_program(&mut parsed.program);
    normalize.numbers.sort_unstable();
    parsed.program.comments.retain(|comment| {
        if has_trailer && comment.span.start as usize >= trailer_start {
            return false;
        }
        if options.drop_decoration_comments && comment.is_block() {
            let end = comment.span.end;
            let index = normalize.numbers.partition_point(|&start| start < end);
            if let Some(&start) = normalize.numbers.get(index) {
                if body[end as usize..start as usize]
                    .chars()
                    .all(|c| c.is_whitespace() || c == '(')
                {
                    return false;
                }
            }
        }
        true
    });
    let mut codegen = CodegenOptions {
        indent_char: IndentChar::Space,
        indent_width: 2,
        ..CodegenOptions::default()
    };
    if options.strip_comments {
        codegen.comments = CommentOptions::disabled();
    }
    let mut code = Codegen::new()
        .with_options(codegen)
        .build(&parsed.program)
        .code;
    if !normalize.jsx_sequences.is_empty() {
        wrap_jsx_sequences(&mut code)?;
    }
    let code = if has_trailer {
        code.trim_end_matches('\n')
    } else {
        &code
    };
    Ok(format!("{preamble}{code}{}", &body[trailer_start..]))
}
